const frame=document.querySelector('iframe'),out=document.querySelector('#results'),results=[];
const wait=ms=>new Promise(r=>setTimeout(r,ms));
function check(name,ok,detail){results.push({name,pass:!!ok,detail});out.textContent=JSON.stringify({passed:results.filter(r=>r.pass).length,total:results.length,results},null,2);if(!ok)throw Error(name);}
async function run(){results.length=0;const w=frame.contentWindow;for(let i=0;i<200&&!w.AtlasIndustrial?.getState().ready;i++)await wait(100);const A=w.AtlasIndustrial,d=w.document;check('model ready',A?.getState().ready);A.setState({reduced:true});const choose=id=>{d.querySelector(`[data-mode="${id}"]`).click();};const input=(id,value)=>{const el=d.querySelector('#'+id);el.value=value;el.dispatchEvent(new Event(el.tagName==='SELECT'?'change':'input',{bubbles:true}));};
check('render meshes loaded',A.inspect().meshCount>=135,A.inspect().meshCount);check('seven groups account for every mesh',A.inspect().groups.reduce((s,g)=>s+g.count,0)===A.inspect().meshCount);check('each group populated',A.inspect().groups.every(g=>g.count>0));
choose('explode');input('spread',100);check('explosion moves meshes',A.inspect().offsetMax>.5);input('spread',0);check('explosion fully reversible',A.inspect().offsetMax<1e-8);
choose('assembly');check('assembly starts separated',A.inspect().offsetMax>.5);for(let i=0;i<6;i++)d.querySelector('#next').click();check('assembly returns exact positions',A.getState().step===6&&A.inspect().offsetMax<1e-8);d.querySelector('#prev').click();check('assembly reverse step',A.getState().step===5&&A.inspect().offsetMax>.5);
choose('section');for(const axis of ['x','y','z']){input('axis',axis);input('cut',25);check('cut plane '+axis,A.inspect().clipped===A.inspect().meshCount&&A.getState().axis===axis);}d.querySelector('#flip').click();check('cut flip',A.getState().flip);
choose('xray');check('clipping removed on transition',A.inspect().clipped===0);input('opacity',30);check('shell opacity control',A.getState().opacity===.3);
choose('isolate');input('group','power');d.querySelector('#hide').click();check('isolation hides remainder',A.inspect().visible===A.inspect().groups.find(g=>g.id==='power').count);d.querySelector('#part-search').value='tire_front';d.querySelector('#part-search').dispatchEvent(new Event('input'));d.querySelector('#parts button').click();check('single mesh list selection',A.getState().mesh==='tire_front'&&A.inspect().visible===1);
choose('mechanism');input('angle',90);check('wheel motion has named parts and rotation',A.getState().angle===90&&A.inspect().wheels.every(w=>w.parts.length>=3));d.querySelector('#zero').click();check('wheel reset',A.getState().angle===0);input('wheel','rear');check('rear wheel selection',A.getState().wheel==='rear');
choose('flow');input('flow','power');input('phase',100);check('conceptual flow endpoint',A.getState().flow==='power'&&A.getState().phase===1);
choose('config');d.querySelector('#luggage').click();d.querySelector('#screen').click();input('paint','olive');check('visibility config',A.inspect().visible<A.inspect().meshCount&&A.getState().paint==='olive');
choose('measure');check('config changes do not leak',A.inspect().visible===A.inspect().meshCount);input('length',2500);check('calibrated envelope',A.getState().lengthMM===2500&&d.querySelector('#metrics').textContent.includes('2500'));d.querySelector('#uncalibrate').click();check('clear calibration',A.getState().lengthMM===0&&d.querySelector('#metrics').textContent.includes('模型单位'));
choose('compare');check('second model exists',A.inspect().comparison&&A.getState().luggage===false);input('paint','olive');check('B config updates',A.getState().paint==='olive');choose('explode');check('compare switch resets original',A.inspect().visible===A.inspect().meshCount&&A.inspect().offsetMax<1e-8);
choose('inspect');input('task','power');for(let i=0;i<3;i++)d.querySelector('#next').click();input('note','QA observation');check('inspection reaches record step',A.getState().inspection===3&&A.getState().note==='QA observation');
const saved=A.getState();A.reset();A.setState(saved);check('state round trip',A.getState().inspection===3&&A.getState().note==='QA observation');let rejected=0;for(const p of [{mode:'bad'},{axis:'bad'},{progress:NaN},{luggage:'false'}]){try{A.setState(p);}catch{rejected++;}}check('invalid state rejected',rejected===4);
choose('flow');d.querySelector('#play').click();check('reduced motion prevents autoplay',A.getState().playing===false);A.setState({reduced:false});d.querySelector('#play').click();await wait(400);d.querySelector('#play').click();check('play and pause flow',A.getState().phase>0&&A.getState().playing===false);
choose('assembly');d.querySelector('#next').click();await wait(1100);check('animated assembly step ends',A.getState().step===1);A.reset();check('reset after animation',A.getState().step===0);check('reset transform finite',Number.isFinite(A.inspect().offsetMax));
out.textContent+='\nALL CHECKS PASSED';}
document.querySelector('#run').onclick=()=>run().catch(e=>{out.textContent+='\nFAILED: '+e.stack;});
